SELECT CASE WHEN birth_year IS NULL OR birth_year NOT REGEXP '^[0-9]{4}$' THEN NULL ELSE FLOOR((YEAR(NOW()) - CAST(birth_year AS UNSIGNED)) / 10) * 10 END AS age_group_start, COUNT(*) AS member_count FROM tb_member WHERE delete_yn = 'N'
AND site_id = #{siteId}
GROUP BY age_group_start ORDER BY age_group_start IS NULL, age_group_start

SELECT age_group_start, SUM(member_count) AS member_count FROM ( SELECT CASE WHEN birth_year IS NULL OR birth_year NOT REGEXP '^[0-9]{4}$' THEN NULL ELSE FLOOR((YEAR(NOW()) - CAST(birth_year AS UNSIGNED)) / 10) * 10 END AS age_group_start, COUNT(*) AS member_count FROM tb_member WHERE delete_yn = 'N'
AND site_id = #{siteId}
GROUP BY age_group_start UNION ALL SELECT CASE WHEN birth_year IS NULL OR birth_year NOT REGEXP '^[0-9]{4}$' THEN NULL ELSE FLOOR((YEAR(NOW()) - CAST(birth_year AS UNSIGNED)) / 10) * 10 END AS age_group_start, COUNT(*) AS member_count FROM tb_member_dormant WHERE 1=1
AND site_id = #{siteId}
GROUP BY age_group_start ) u GROUP BY age_group_start ORDER BY age_group_start IS NULL, age_group_start
